// Dedup returns a new slice with duplicates removed, preserving the first-seen order.
func Dedup(in []int) []int {
	seen := make(map[int]bool)
	var result []int

	for _, value := range in {
		if _, exists := seen[value]; !exists {
			seen[value] = true
			result = append(result, value)
		}
	}

	return result
}

