func Chunk[T any](s []T, n int) [][]T {
	if n < 1 {
		return nil
	}

	var chunks [][]T
	for i := 0; i < len(s); i += n {
		end := i + n
		if end > len(s) {
			end = len(s)
		}
		chunks = append(chunks, s[i:end])
	}
	return chunks
}

