func Balanced(s string) bool {
	stack := []rune{}

	for _, ch := range s {
		switch ch {
		case '(', '[', '{':
			stack = append(stack, ch)
		case ')':
			if len(stack) == 0 || stack[len(stack)-1] != '(' {
				return false
			}
			stack = stack[:len(stack)-1]
		case ']':
			if len(stack) == 0 || stack[len(stack)-1] != '[' {
				return false
			}
			stack = stack[:len(stack)-1]
		case '}':
			if len(stack) == 0 || stack[len(stack)-1] != '{' {
				return false
			}
			stack = stack[:len(stack)-1]
		}
	}

	return len(stack) == 0
}

func main() {
	fmt.Println(Balanced("()[]{}")) // true
	fmt.Println(Balanced("([{}])")) // true
	fmt.Println(Balanced("(]"))     // false
	fmt.Println(Balanced("([)]"))   // false
	fmt.Println(Balanced("{[]}"))   // true
}

