func Caesar(s string, n int) string {
	var result strings.Builder
	for _, r := range s {
		if r >= 'a' && r <= 'z' {
			result.WriteRune('a' + (r-'a'+rune(n))%26)
		} else if r >= 'A' && r <= 'Z' {
			result.WriteRune('A' + (r-'A'+rune(n))%26)
		} else {
			result.WriteRune(r)
		}
	}
	return result.String()
}

