type Ring struct {
	buf    []int
	start  int
	length int
	cap    int
}

func NewRing(cap int) *Ring {
	return &Ring{
		buf:    make([]int, cap),
		start:  0,
		length: 0,
		cap:    cap,
	}
}

func (r *Ring) Push(v int) {
	if r.length == r.cap {
		r.start = (r.start + 1) % r.cap
	} else {
		r.length++
	}
	r.buf[(r.start+r.length-1)%r.cap] = v
}

func (r *Ring) Items() []int {
	if r.length == 0 {
		return nil
	}
	items := make([]int, r.length)
	for i := 0; i < r.length; i++ {
		items[i] = r.buf[(r.start+i)%r.cap]
	}
	return items
}

