func Rotate(m [][]int) {
    n := len(m)
    for layer := 0; layer < n/2; layer++ {
        first := layer
        last := n - 1 - layer
        for i := first; i < last; i++ {
            offset := i - first
            top := m[first][i]
            m[first][i] = m[last-offset][first]
            m[last-offset][first] = m[last][last-offset]
            m[last][last-offset] = m[i][last]
            m[i][last] = top
        }
    }
}

