func ParallelSum(nums []int, workers int) int {
	jobs := make(chan int, len(nums))
	var wg sync.WaitGroup
	sum := 0
	var mu sync.Mutex

	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for num := range jobs {
				mu.Lock()
				sum += num
				mu.Unlock()
			}
		}()
	}

	for _, num := range nums {
		jobs <- num
	}
	close(jobs)

	wg.Wait()
	return sum
}

